#include "PluginEditor.h"
EvenAudioProcessorEditor::EvenAudioProcessorEditor(EvenAudioProcessor&x):AudioProcessorEditor(&x),p(x){knobs={&h2,&drive,&asym,&bias,&warmth,&iron,&mix,&output};const char*ids[]={"h2","drive","asym","bias","warmth","iron","mix","output"};for(int i=0;i<8;++i){auto*k=knobs[i];k->setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);k->setTextBoxStyle(juce::Slider::TextBoxBelow,false,76,20);addAndMakeVisible(*k);sa.push_back(std::make_unique<SA>(p.apvts,ids[i],*k));}addAndMakeVisible(pure);addAndMakeVisible(solo);pa=std::make_unique<BA>(p.apvts,"pure",pure);soa=std::make_unique<BA>(p.apvts,"solo",solo);setSize(900,470);}
void EvenAudioProcessorEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff0b0b0d));g.setColour(juce::Colour(0xffff8a24));g.setFont(52);g.drawText("E V E N",20,20,getWidth()-40,60,juce::Justification::centred);g.setFont(18);g.drawText("SECOND HARMONIC BEAST",20,78,getWidth()-40,28,juce::Justification::centred);g.setFont(14);g.drawText("2ND HARMONIC      DRIVE      ASYMMETRY      BIAS      WARMTH      IRON      MIX      OUTPUT",20,330,getWidth()-40,25,juce::Justification::centred);g.setFont(16);g.drawText("EVERYTHING IMPORTANT GOES TO 11",20,420,getWidth()-40,25,juce::Justification::centred);}
void EvenAudioProcessorEditor::resized(){int x=20;for(auto*k:knobs){k->setBounds(x,125,98,180);x+=108;}pure.setBounds(300,370,130,30);solo.setBounds(470,370,130,30);}
